#include <array>
#include <iostream>

template <typename T, std::size_t Size>
void displaySubarray(const std::array<T, Size>& arr, std::size_t low, std::size_t high) {
    for (std::size_t i = 0; i < low; ++i) {
        std::cout << "   ";
    }
    for (std::size_t i = low; i <= high; ++i) {
        std::cout << arr[i] << ' ';
    }
    std::cout << '\n';
}

template <typename T, std::size_t Size>
void traceSplit(const std::array<T, Size>& arr, std::size_t low, std::size_t high) {
    if (high > low) {
        std::size_t middle = low + (high - low) / 2;
        std::cout << "split [" << low << ".." << high << "]: ";
        displaySubarray(arr, low, high);
        traceSplit(arr, low, middle);
        traceSplit(arr, middle + 1, high);
    }
}

int main() {
    std::array<int, 6> values{45, 12, 89, 34, 70, 23};
    std::cout << "Initial array:\n";
    displaySubarray(values, 0, values.size() - 1);
    std::cout << "Recursive splits:\n";
    traceSplit(values, 0, values.size() - 1);
    return 0;
}

#include <array>
#include <iostream>

template <typename T, std::size_t Size>
void merge(std::array<T, Size>& items, std::size_t left, std::size_t middle, std::size_t right) {
    std::array<T, Size> combined;
    std::size_t leftIdx = left;
    std::size_t rightIdx = middle + 1;
    std::size_t combIdx = left;

    while (leftIdx <= middle && rightIdx <= right) {
        if (items[leftIdx] <= items[rightIdx]) {
            combined[combIdx++] = items[leftIdx++];
        } else {
            combined[combIdx++] = items[rightIdx++];
        }
    }

    while (leftIdx <= middle) {
        combined[combIdx++] = items[leftIdx++];
    }
    while (rightIdx <= right) {
        combined[combIdx++] = items[rightIdx++];
    }

    for (std::size_t i = left; i <= right; ++i) {
        items[i] = combined[i];
    }
}

template <typename T, std::size_t Size>
void mergeSort(std::array<T, Size>& items, std::size_t low, std::size_t high) {
    if (high > low) {
        std::size_t middle = low + (high - low) / 2;
        mergeSort(items, low, middle);
        mergeSort(items, middle + 1, high);
        merge(items, low, middle, high);
    }
}

int main() {
    std::array<int, 8> data{30, 47, 22, 67, 79, 18, 60, 26};
    mergeSort(data, 0, data.size() - 1);
    std::cout << "Sorted: ";
    for (int num : data) {
        std::cout << num << ' ';
    }
    std::cout << '\n';
    return 0;
}
